steps.run:
STATUS_ICON=""
STATUS_PREFIX=""
case "$STATUS" in
  success)
    STATUS_ICON="✅";
    STATUS_PREFIX="succeeded";
    ;;
  failure)
    STATUS_ICON="❌";
    STATUS_PREFIX="failed";
    ;;
  partial)
    STATUS_ICON="⚠️";
    STATUS_PREFIX="";
    ;;
  *)
    STATUS_ICON="ℹ️";
    STATUS_PREFIX="update";
    ;;
esac
# Omit ", version …" when no version is supplied; older callers that
# pass a version still render unchanged.
VERSION_VALUE=${VERSION_INPUT:-n/a}
VERSION_LINE=""
if [ -n "$VERSION_INPUT" ]; then
  VERSION_LINE=", version ${VERSION_INPUT}"
fi
# Drop the trailing status word when it would be redundant (partial).
TITLE_SUFFIX=""
if [ -n "$STATUS_PREFIX" ]; then
  TITLE_SUFFIX=" ${STATUS_PREFIX}"
fi

payload=$(cat <<EOF
{
  "text": "${STATUS_ICON} ${TITLE}${TITLE_SUFFIX}${VERSION_LINE} in ${GITHUB_REPO}",
  "blocks": [
    {
      "type": "header",
      "text": { "type": "plain_text", "text": "${STATUS_ICON} ${TITLE}${TITLE_SUFFIX}", "emoji": true }
    },
    {
      "type": "section",
      "text": { "type": "mrkdwn", "text": "See workflow details below. @group-sdk" }
    },
    {
      "type": "section",
      "fields": [
        { "type": "mrkdwn", "text": "*Repository*\n${GITHUB_REPO}" },
        { "type": "mrkdwn", "text": "*Workflow*\n${GITHUB_WORKFLOW}" },
        { "type": "mrkdwn", "text": "*Ref*\n${GITHUB_REFNAME}" },
        { "type": "mrkdwn", "text": "*Actor*\n${GITHUB_ACTOR}" },
        { "type": "mrkdwn", "text": "*Version*\n${VERSION_VALUE}" }
      ]
    },
    {
      "type": "actions",
      "elements": [
        {
          "type": "button",
          "text": { "type": "plain_text", "text": "View Run" },
          "url": "https://github.com/${GITHUB_REPO}/actions/runs/${{ github.run_id }}"
        },
        {
          "type": "button",
          "text": { "type": "plain_text", "text": "View Commit" },
          "url": "https://github.com/${GITHUB_REPO}/commit/${{ github.sha }}"
        }
      ]
    },
    {
      "type": "context",
      "elements": [
        { "type": "mrkdwn", "text": "Commit: ${{ github.sha }}" }
      ]
    }
  ]
}
EOF
)

curl -X POST -H 'Content-type: application/json' --data "$payload" ${{ secrets.SLACK_CLIENT_LIBS_WEBHOOK }}
